const msg = $input.first().json;
const text = (msg.content || []).filter(b => b.type === 'text').map(b => b.text).join('').trim().replace(/^```(?:json)?\s*|\s*```$/g, '');
// Anything unparseable stays in the admin queue (risk 100)
let r = { risk: 100, reason: 'No se pudo evaluar automáticamente' };
try {
  const j = JSON.parse(text);
  if (Number.isInteger(j.risk) && j.risk >= 0 && j.risk <= 100) r = { risk: j.risk, reason: String(j.reason || '').slice(0, 500) };
} catch (e) {}
const src = $('Webhook').first().json.body;
return [{ json: { petId: src.petId, riskScore: r.risk, reason: r.reason, version: src.version, inputTokens: msg.usage?.input_tokens ?? 0, outputTokens: msg.usage?.output_tokens ?? 0 } }];
